input.command:
mkdir -p bootstrap && cd bootstrap
cat > versions.tf <<'EOF'
terraform {
  required_version = ">= 1.10.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 6.0"
    }
  }
}
EOF
cat > variables.tf <<'EOF'
variable "region" {
  type    = string
  default = "eu-north-1"
}

variable "bucket_name" {
  type        = string
  default     = null
  description = "State bucket name. Defaults to tfstate-<account id>-<region>."
}
EOF
cat > main.tf <<'EOF'
provider "aws" {
  region = var.region
}

data "aws_caller_identity" "current" {}

locals {
  bucket_name = coalesce(var.bucket_name, "tfstate-${data.aws_caller_identity.current.account_id}-${var.region}")
}

resource "aws_s3_bucket" "state" {
  bucket = local.bucket_name

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "state" {
  bucket = aws_s3_bucket.state.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "state" {
  bucket = aws_s3_bucket.state.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "aws:kms"
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_public_access_block" "state" {
  bucket = aws_s3_bucket.state.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "state" {
  bucket = aws_s3_bucket.state.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_lifecycle_configuration" "state" {
  bucket = aws_s3_bucket.state.id

  rule {
    id     = "expire-noncurrent-state-versions"
    status = "Enabled"

    filter {}

    noncurrent_version_expiration {
      noncurrent_days = 90
    }

    abort_incomplete_multipart_upload {
      days_after_initiation = 7
    }
  }
}

data "aws_iam_policy_document" "state" {
  statement {
    sid       = "DenyInsecureTransport"
    effect    = "Deny"
    actions   = ["s3:*"]
    resources = [aws_s3_bucket.state.arn, "${aws_s3_bucket.state.arn}/*"]

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }
}

resource "aws_s3_bucket_policy" "state" {
  bucket     = aws_s3_bucket.state.id
  policy     = data.aws_iam_policy_document.state.json
  depends_on = [aws_s3_bucket_public_access_block.state]
}
EOF
cat > outputs.tf <<'EOF'
output "bucket" {
  value = aws_s3_bucket.state.id
}

output "region" {
  value = var.region
}
EOF
cd ..
cat > backend.tf <<'EOF'
# Partial configuration: the bucket name is passed at init time
# (terraform init -backend-config="bucket=<name>"), see README.
terraform {
  backend "s3" {
    key          = "reports/terraform.tfstate"
    region       = "eu-north-1"
    encrypt      = true
    use_lockfile = true
  }
}
EOF
cat > .gitignore <<'EOF'
.terraform/
*.tfstate
*.tfstate.*
*.tfplan
crash.log
EOF
cat > README.md <<'EOF'
# reports

Terraform for the reports bucket and the key the nightly export job uploads with. The job reads
the key from `terraform output`.

State is stored in S3 (versioned, KMS-encrypted, public access blocked, TLS-only, native S3
lockfile locking so no DynamoDB table is needed). Requires Terraform >= 1.10.

## One-time bootstrap (one person, once)

`bootstrap/` creates the state bucket. Its own state is local (it can't live in a bucket that
doesn't exist yet); it holds no secrets and can be re-imported if lost.

```sh
cd bootstrap
terraform init
terraform apply          # bucket defaults to tfstate-<account id>-<region>
terraform output -raw bucket
```

Optionally keep `bootstrap/terraform.tfstate` somewhere safe. The bucket has `prevent_destroy`.

## Everyday workflow (everyone)

Use AWS credentials with `s3:ListBucket` on the bucket and `s3:GetObject`/`PutObject`/`DeleteObject`
on `reports/*` (the lockfile is `reports/terraform.tfstate.tflock`) plus KMS use of the S3 key.

```sh
terraform init -backend-config="bucket=<bucket from bootstrap output>"
terraform plan
terraform apply
```

## Migrating the existing local state (once, by whoever holds `terraform.tfstate`)

```sh
terraform init -migrate-state -backend-config="bucket=<bucket>"
```

Answer `yes` to copy the state, confirm with `terraform plan` (expect no changes), then delete the
local `terraform.tfstate*` files. Do this before anyone else runs `apply`.

## Notes

- The state contains the IAM access key secret (`aws_iam_access_key.uploader`), so restrict bucket
  access to people who may read that secret.
- Never commit state files; `.gitignore` excludes them.
EOF
terraform fmt -recursive; cd bootstrap && terraform init -backend=false >/dev/null && terraform validate; cd .. && terraform init -backend=false >/dev/null && terraform validate; git status --short

